entries[4141] = { ["name"] = "Foliant des Essenherbeizauberns", ["text"] = "Klassen: Magier\nBenötigt Stufe 6\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 1).\nZaubert Speisen herbei, die den Magier sowie seine Verbündeten mit etwas Essbarem versorgen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:" }
entries[4143] = { ["name"] = "Foliant des Essenherbeizauberns II", ["text"] = "Klassen: Magier\nBenötigt Stufe 12\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 2).\nZaubert 20 Laibe Brot herbei, die den Magier sowie seine Verbündeten mit etwas Essbarem versorgen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes Brot\nHerbeigezauberter Gegenstand\nBenötigt Stufe 5\nBenutzen: Stellt im Verlauf von 21 Sek. insgesamt 243.6 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4145] = { ["name"] = "Foliant des Manaedelsteinherbeizauberns", ["text"] = "Klassen: Magier\nBenötigt Stufe 28\nBenutzen: Lehrt 'Manaedelstein herbeizaubern'.\nZaubert einen Manaedelstein herbei, der zum sofortigen Wiederherstellen von 492 Mana verwendet werden kann.\nVerkaufspreis:\nManaedelstein\nWird beim Aufheben gebunden\nEinzigartig: [Mana Gem] (1)\nBenutzen: Stellt 12103 Mana wieder her. (2 Min Abklingzeit)\n3 Aufladungen" }
entries[4146] = { ["name"] = "Foliant der Verwandlung: Schaf", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Verwandlung: Schaf'.\nVerwandelt den Feind bis zu 10 Sek. lang in ein hilfloses Schaf, das weder Zauber wirken noch angreifen kann und sich um 60% langsamer bewegt.\nVerkaufspreis:" }
entries[4147] = { ["name"] = "Foliant des Essenherbeizauberns III", ["text"] = "Klassen: Magier\nBenötigt Stufe 22\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 3).\nZaubert 20 Laibe Roggenbrot herbei, die den Magier sowie seine Verbündeten mit etwas Essbarem versorgen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes Roggenbrot\nHerbeigezauberter Gegenstand\nBenötigt Stufe 15\nBenutzen: Stellt im Verlauf von 24 Sek. insgesamt 552 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4148] = { ["name"] = "Foliant des Gegenzaubers", ["text"] = "Klassen: Magier\nBenötigt Stufe 24\nBenutzen: Lehrt 'Gegenzauber'.\nKontert das Zauberwirken des Feindes und verhindert 7 Sek. lang, dass ein Zauber dieser Art der Magie gewirkt werden kann.\nVerkaufspreis:" }
entries[4149] = { ["name"] = "Foliant des Frostschilds III", ["text"] = "Klassen: Magier\nBenötigt Stufe 34\n\"Lehrt 'Frostschild' (Rang 3).\"\nVerkaufspreis:" }
entries[4150] = { ["name"] = "Foliant des Wasserherbeizauberns IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 30\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 4).\nZaubert 20 Flaschen Quellwasser herbei, die den Magier sowie seine Verbündeten mit etwas Trinkbarem versorgen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes Quellwasser\nHerbeigezauberter Gegenstand\nBenötigt Stufe 25\nBenutzen: Stellt im Verlauf von 27 Sek. insgesamt 1345 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[4151] = { ["name"] = "Foliant des Frostblitzes IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\n\"Lehrt 'Frostblitz' (Rang 4).\"\nVerkaufspreis:" }
entries[4152] = { ["name"] = "Foliant des Essenherbeizauberns IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 32\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 4).\nZaubert 20 Laibe Pumpernickel herbei, die den Magier sowie seine Verbündeten mit etwas Essbarem versorgen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezauberter Pumpernickel\nHerbeigezauberter Gegenstand\nBenötigt Stufe 25\nBenutzen: Stellt im Verlauf von 27 Sek. insgesamt 874.8 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4153] = { ["name"] = "Foliant der arkanen Geschosse III", ["text"] = "Klassen: Magier\nBenötigt Stufe 24\n\"Lehrt 'Arkane Geschosse' (Rang 3).\"\nVerkaufspreis:" }
entries[4154] = { ["name"] = "Foliant der Verlangsamung II", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Langsamkeit' (Rang 2).\nVerlangsamt 8 Sek. lang die Bewegung des Feindes um 50% und sein Angriffstempo um 50%.\nVerkaufspreis:" }
