entries[4166] = { ["name"] = "Buchband: Siegel des Schutzes", ["text"] = "Klassen: Paladin\nBenötigt Stufe 8\nBenutzen: Lehrt 'Siegel des Schutzes' (Rang 1).\nEin anvisiertes Gruppen- oder Schlachtzugsmitglied ist 10 Sek. lang vor allen körperlichen Angriffen geschützt, allerdings kann es dabei weder angreifen noch körperliche Fähigkeiten einsetzen. Spieler können pro Paladin immer nur von einer Hand berührt werden. Kann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 1 Min. lang anhält.\nVerkaufspreis:" }
entries[4167] = { ["name"] = "Buchband: Richturteil", ["text"] = "Klassen: Paladin\nBenötigt Stufe 40\nBenutzen: Lehrt 'Richturteil'.\nSchleudert Blitze heiliger Macht in alle Richtungen, die (0.61 * Spell power + 184 ) Heiligschaden verursachen. Dieser Schaden wird unter allen Zielen im Umkreis von 10 Metern aufgeteilt und betäubt 3 Sek. lang alle Dämonen [ Glyphe 'Heiliger Zorn' : Drachkin, Elementare ] sowie Untoten.\nVerkaufspreis:" }
entries[4168] = { ["name"] = "Schrifttafel des Totems der Einschnürung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 16\nBenutzen: Lehrt 'Totem der Erdbindung'.\nBeschwört ein Totem der Erdbindung mit 5 Gesundheit zu Füßen des Zaubernden, das das Bewegungstempo von Feinden im Umkreis von 10 Metern verlangsamt. Hält 45 Sek. lang an.\nVerkaufspreis:" }
